/**
 * Read-only, context-sensitive help for quiz settings.
 *
 * This module never modifies values, submits forms, or applies access rules.
 * Moodle forms and quiz access plugins remain authoritative.
 *
 * @module mod_quiz/settings_guidance
 */

const GUIDANCE_SELECTOR = '[data-region="quiz-settings-guidance"]';
const MESSAGE_SELECTOR = '[data-region="quiz-settings-guidance-message"]';
const PERIODS = ['during', 'immediately', 'open', 'closed'];

/**
 * Find the actual input behind a Moodle form name without constructing selectors
 * for bracketed form names such as timeclose[enabled].
 *
 * @param {HTMLFormElement} form Moodle form.
 * @param {string} name Native field name.
 * @returns {HTMLElement|null}
 */
const control = (form, name) => {
    const found = form.elements.namedItem(name);
    if (!found) {
        return null;
    }
    return found.length && !found.tagName ? found[0] : found;
};

/**
 * Formslib may hide or disable fields. Never explain an inactive field as active.
 *
 * @param {HTMLElement|null} input Form input.
 * @returns {boolean}
 */
const active = input => {
    if (!input || input.disabled) {
        return false;
    }
    const hidden = input.closest('[hidden], [aria-hidden="true"], .d-none, .hidden');
    if (hidden) {
        return false;
    }
    const item = input.closest('.fitem');
    return !item || (!item.hidden && item.style.display !== 'none');
};

/**
 * @param {HTMLFormElement} form Moodle form.
 * @param {string} name Native field name.
 * @returns {string|null} Null if the field cannot currently be used.
 */
const value = (form, name) => {
    const input = control(form, name);
    return active(input) ? String(input.value) : null;
};

/**
 * @param {HTMLFormElement} form Moodle form.
 * @param {string} name Native checkbox name.
 * @returns {boolean}
 */
const checked = (form, name) => {
    const input = control(form, name);
    return active(input) && input.checked === true;
};

/**
 * Render guidance from translated strings already provided by the server.
 *
 * @param {HTMLFormElement} form Native form, never mutated.
 * @param {HTMLElement} region Existing guidance region.
 */
export const renderGuidance = (form, region) => {
    const message = region.querySelector(MESSAGE_SELECTOR);
    if (!message) {
        return;
    }
    const string = name => region.getAttribute('data-message-' + name) || '';
    const notes = [string('base')];
    const add = name => {
        if (string(name)) {
            notes.push(string(name));
        }
    };

    switch (region.dataset.guidance) {
        case 'timing':
            if (checked(form, 'timeopen[enabled]')) {
                add('open');
            }
            if (checked(form, 'duedate[enabled]')) {
                add('due');
            }
            if (checked(form, 'timeclose[enabled]')) {
                add('close');
            }
            if (checked(form, 'timelimit[enabled]')) {
                add('limit');
            }
            if (value(form, 'overduehandling') === 'graceperiod') {
                add('grace');
            }
            break;
        case 'grading': {
            const attempts = value(form, 'attempts');
            if (attempts === '0') {
                add('unlimited');
            } else if (attempts === '1') {
                add('single');
            } else if (attempts !== null && Number(attempts) > 1) {
                add('multiple');
            }
            break;
        }
        case 'layout':
            if (value(form, 'navmethod') === 'sequential') {
                add('sequential');
            } else if (value(form, 'navmethod') === 'free') {
                add('free');
            }
            if (checked(form, 'repaginatenow')) {
                add('repaginate');
            }
            break;
        case 'behaviour':
            if (value(form, 'canredoquestions') === '1') {
                add('redo');
            }
            if (value(form, 'attemptonlast') === '1') {
                add('reuse');
            }
            break;
        case 'review': {
            const closing = checked(form, 'timeclose[enabled]');
            if (!closing) {
                add('closeoff');
            }
            const available = period => period !== 'closed' || closing;
            if (PERIODS.some(period => available(period) && checked(form, 'rightanswer' + period))) {
                add('answers');
            }
            if (PERIODS.some(period => available(period) && checked(form, 'marks' + period))) {
                add('marks');
            }
            break;
        }
        case 'restrictions':
            // Only test presence; never copy a password into the DOM or diagnostics.
            if (value(form, 'quizpassword')) {
                add('password');
            }
            if (value(form, 'subnet')) {
                add('subnet');
            }
            if (checked(form, 'delay1[enabled]') || checked(form, 'delay2[enabled]')) {
                add('delays');
            }
            if (value(form, 'browsersecurity') && value(form, 'browsersecurity') !== 'none') {
                add('browser');
            }
            break;
        case 'feedback':
            if (control(form, 'grade')?.value === '0') {
                add('nograde');
            }
            break;
        default:
            return;
    }

    const content = notes.filter(Boolean).join(' ');
    if (message.textContent !== content) {
        message.textContent = content;
    }
};

/**
 * Attach once to each Moodle form. The delayed pass observes formslib's
 * change-driven hideIf/disabledIf updates without replacing them.
 */
export const init = () => {
    const forms = new Map();
    document.querySelectorAll(GUIDANCE_SELECTOR).forEach(region => {
        const form = region.closest('form');
        if (!form) {
            return;
        }
        if (!forms.has(form)) {
            forms.set(form, []);
        }
        forms.get(form).push(region);
    });
    forms.forEach((regions, form) => {
        if (form.dataset.quizSettingsGuidanceInitialised === '1') {
            return;
        }
        form.dataset.quizSettingsGuidanceInitialised = '1';
        const update = () => regions.forEach(region => renderGuidance(form, region));
        const updateAfterNativeRules = () => {
            update();
            window.setTimeout(update, 100);
        };
        form.addEventListener('change', updateAfterNativeRules);
        update();
    });
};
